INSERT INTO public.exercises (id,name,body_part,equipment,target,secondary_muscles,instructions,description,difficulty,category) VALUES
('recovery-childs-pose','Child''s Pose','back','body weight','spine',ARRAY['glutes','shoulders']::text[],ARRAY['Kneel with the big toes together and knees wide.','Set the breath before the first repetition.','Sit the hips back to the heels and reach the arms long, breathing into the back of the ribs.','Let the whole spine soften with every exhale.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Child''s Pose is a mobility exercise for the spine with support from the glutes and shoulders. Kneel with the big toes together and knees wide. Sit the hips back to the heels and reach the arms long, breathing into the back of the ribs. Let the whole spine soften with every exhale.','beginner','mobility'),
('recovery-9090-hip-rotation','90/90 Hip Rotation','upper legs','body weight','glutes',ARRAY['hip flexors','abs']::text[],ARRAY['Sit on the floor with both knees bent at ninety degrees, one leg in front and one to the side.','Set the breath before the first repetition.','Rotate both knees to the other side with control, keeping the chest tall.','Move slowly and stop short of any pinching in the hip.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'90/90 Hip Rotation is a mobility exercise for the glutes with support from the hip flexors and abs. Sit on the floor with both knees bent at ninety degrees, one leg in front and one to the side. Rotate both knees to the other side with control, keeping the chest tall. Move slowly and stop short of any pinching in the hip.','beginner','mobility'),
('recovery-thoracic-rotation-quadruped','Thoracic Spine Rotation (Quadruped)','back','body weight','spine',ARRAY['shoulders']::text[],ARRAY['Kneel on all fours with one hand behind the head.','Set the breath before the first repetition.','Rotate the elbow up to the ceiling opening the chest, then thread it under the body.','Rotate from the upper back, keeping the hips completely still.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Thoracic Spine Rotation (Quadruped) is a mobility exercise for the spine with support from the shoulders. Kneel on all fours with one hand behind the head. Rotate the elbow up to the ceiling opening the chest, then thread it under the body. Rotate from the upper back, keeping the hips completely still.','beginner','mobility'),
('recovery-thread-the-needle','Thread the Needle','back','body weight','upper back',ARRAY['shoulders','spine']::text[],ARRAY['Kneel on all fours with the hips over the knees.','Set the breath before the first repetition.','Slide one arm under the body until the shoulder and side of the head rest on the floor, then unwind.','Breathe into the stretch rather than forcing depth.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Thread the Needle is a mobility exercise for the upper back with support from the shoulders and spine. Kneel on all fours with the hips over the knees. Slide one arm under the body until the shoulder and side of the head rest on the floor, then unwind. Breathe into the stretch rather than forcing depth.','beginner','mobility'),
('recovery-couch-stretch','Couch Stretch','upper legs','body weight','quads',ARRAY['hip flexors']::text[],ARRAY['Kneel in front of a wall or sofa and place the back foot up behind you.','Set the breath before the first repetition.','Tuck the pelvis and raise the torso until the front of the hip and thigh lengthen.','Keep the pelvis tucked; that is where the stretch comes from.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Couch Stretch is a stretching exercise for the quads with support from the hip flexors. Kneel in front of a wall or sofa and place the back foot up behind you. Tuck the pelvis and raise the torso until the front of the hip and thigh lengthen. Keep the pelvis tucked; that is where the stretch comes from.','intermediate','stretching'),
('recovery-figure-4-stretch','Figure-4 Stretch','upper legs','body weight','glutes',ARRAY['hip flexors']::text[],ARRAY['Lie supine and cross one ankle over the opposite knee.','Set the breath before the first repetition.','Draw the supporting thigh towards the chest until the glute lengthens.','Keep the head and shoulders relaxed on the floor.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Figure-4 Stretch is a stretching exercise for the glutes with support from the hip flexors. Lie supine and cross one ankle over the opposite knee. Draw the supporting thigh towards the chest until the glute lengthens. Keep the head and shoulders relaxed on the floor.','beginner','stretching'),
('recovery-butterfly-stretch','Butterfly Stretch','upper legs','body weight','adductors',ARRAY['hip flexors']::text[],ARRAY['Sit tall with the soles of the feet together.','Set the breath before the first repetition.','Let the knees soften towards the floor and hinge gently forward from the hips.','Never bounce the knees; let gravity do the work.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Butterfly Stretch is a stretching exercise for the adductors with support from the hip flexors. Sit tall with the soles of the feet together. Let the knees soften towards the floor and hinge gently forward from the hips. Never bounce the knees; let gravity do the work.','beginner','stretching'),
('recovery-deep-squat-hold','Deep Squat Hold','upper legs','body weight','glutes',ARRAY['adductors','calves']::text[],ARRAY['Stand with the feet a little wider than the hips and toes slightly out.','Set the breath before the first repetition.','Sit into the deepest comfortable squat and hold, using the elbows to open the knees.','Keep the heels down; hold a support if balance is an issue.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Deep Squat Hold is a mobility exercise for the glutes with support from the adductors and calves. Stand with the feet a little wider than the hips and toes slightly out. Sit into the deepest comfortable squat and hold, using the elbows to open the knees. Keep the heels down; hold a support if balance is an issue.','beginner','mobility'),
('recovery-ankle-rocks','Ankle Rocks (Dorsiflexion)','lower legs','body weight','calves',ARRAY['quads']::text[],ARRAY['Half kneel with the front foot flat and a wall or support in front.','Set the breath before the first repetition.','Drive the front knee forward over the toes and return, keeping the heel glued down.','Small, repeated rocks beat one long push.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Ankle Rocks (Dorsiflexion) is a mobility exercise for the calves with support from the quads. Half kneel with the front foot flat and a wall or support in front. Drive the front knee forward over the toes and return, keeping the heel glued down. Small, repeated rocks beat one long push.','beginner','mobility'),
('recovery-hip-cars','Hip CARs','upper legs','body weight','hip flexors',ARRAY['glutes','abs']::text[],ARRAY['Stand tall holding a support, or kneel on all fours.','Set the breath before the first repetition.','Take one hip slowly through its full circle of motion, keeping the rest of the body still.','Move at a crawl: the slower the circle, the better the control.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Hip CARs is a mobility exercise for the hip flexors with support from the glutes and abs. Stand tall holding a support, or kneel on all fours. Take one hip slowly through its full circle of motion, keeping the rest of the body still. Move at a crawl: the slower the circle, the better the control.','intermediate','mobility'),
('recovery-shoulder-cars','Shoulder CARs','shoulders','body weight','delts',ARRAY['upper back']::text[],ARRAY['Stand tall with the ribs down and one arm by the side.','Set the breath before the first repetition.','Trace the largest possible circle with the arm, keeping the trunk absolutely still.','If the ribs flare or the trunk twists, make the circle smaller.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Shoulder CARs is a mobility exercise for the delts with support from the upper back. Stand tall with the ribs down and one arm by the side. Trace the largest possible circle with the arm, keeping the trunk absolutely still. If the ribs flare or the trunk twists, make the circle smaller.','intermediate','mobility'),
('recovery-arm-circles','Arm Circles','shoulders','body weight','delts',ARRAY['upper back']::text[],ARRAY['Stand tall with the arms out to the sides.','Set the breath before the first repetition.','Draw controlled circles forward, then backward, gradually growing them.','Keep the shoulders down away from the ears.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Arm Circles is a mobility exercise for the delts with support from the upper back. Stand tall with the arms out to the sides. Draw controlled circles forward, then backward, gradually growing them. Keep the shoulders down away from the ears.','beginner','mobility'),
('recovery-scapular-wall-slides','Scapular Wall Slides','shoulders','body weight','upper back',ARRAY['delts']::text[],ARRAY['Stand with the back, head and arms against a wall in a goalpost position.','Set the breath before the first repetition.','Slide the arms overhead keeping contact, then return squeezing the shoulder blades down.','Keep the low back close to the wall throughout.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Scapular Wall Slides is a mobility exercise for the upper back with support from the delts. Stand with the back, head and arms against a wall in a goalpost position. Slide the arms overhead keeping contact, then return squeezing the shoulder blades down. Keep the low back close to the wall throughout.','beginner','mobility'),
('recovery-doorway-chest-stretch','Doorway Chest Stretch','chest','body weight','pectorals',ARRAY['shoulders']::text[],ARRAY['Stand in a doorway with the forearms on the frame at shoulder height.','Set the breath before the first repetition.','Step gently through until the chest lengthens and hold, breathing steadily.','Keep the ribs down so the stretch stays in the chest.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Doorway Chest Stretch is a stretching exercise for the pectorals with support from the shoulders. Stand in a doorway with the forearms on the frame at shoulder height. Step gently through until the chest lengthens and hold, breathing steadily. Keep the ribs down so the stretch stays in the chest.','beginner','stretching'),
('recovery-cross-body-shoulder-stretch','Cross-Body Shoulder Stretch','shoulders','body weight','delts',ARRAY['upper back']::text[],ARRAY['Stand or sit tall and bring one arm across the chest.','Set the breath before the first repetition.','Use the other arm to draw it closer and hold, keeping the shoulder down.','Do not pull on the elbow joint itself.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Cross-Body Shoulder Stretch is a stretching exercise for the delts with support from the upper back. Stand or sit tall and bring one arm across the chest. Use the other arm to draw it closer and hold, keeping the shoulder down. Do not pull on the elbow joint itself.','beginner','stretching'),
('recovery-neck-rotations','Neck Rotations','neck','body weight','neck',ARRAY['upper back']::text[],ARRAY['Sit or stand tall with the shoulders relaxed.','Set the breath before the first repetition.','Turn the head slowly to one side, pause, and return through centre to the other.','Move only as far as is completely comfortable.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Neck Rotations is a mobility exercise for the neck with support from the upper back. Sit or stand tall with the shoulders relaxed. Turn the head slowly to one side, pause, and return through centre to the other. Move only as far as is completely comfortable.','beginner','mobility'),
('recovery-cervical-side-bend','Cervical Side Bend Stretch','neck','body weight','neck',ARRAY['upper back']::text[],ARRAY['Sit tall with one hand holding the edge of the chair.','Set the breath before the first repetition.','Tilt the opposite ear towards the shoulder and hold, breathing slowly.','Let the weight of the head create the stretch.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Cervical Side Bend Stretch is a stretching exercise for the neck with support from the upper back. Sit tall with one hand holding the edge of the chair. Tilt the opposite ear towards the shoulder and hold, breathing slowly. Let the weight of the head create the stretch.','beginner','stretching'),
('recovery-seated-forward-fold','Seated Forward Fold','upper legs','body weight','hamstrings',ARRAY['spine','calves']::text[],ARRAY['Sit with the legs extended and the spine tall.','Set the breath before the first repetition.','Hinge from the hips and reach along the legs, softening with each exhale.','Bend the knees slightly rather than rounding hard through the low back.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Seated Forward Fold is a stretching exercise for the hamstrings with support from the spine and calves. Sit with the legs extended and the spine tall. Hinge from the hips and reach along the legs, softening with each exhale. Bend the knees slightly rather than rounding hard through the low back.','beginner','stretching'),
('recovery-supine-spinal-twist','Supine Spinal Twist','back','body weight','spine',ARRAY['obliques','glutes']::text[],ARRAY['Lie supine with the arms out wide and the knees bent.','Set the breath before the first repetition.','Drop both knees to one side and turn the head the other way, then change sides.','Keep both shoulders heavy on the floor.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Supine Spinal Twist is a stretching exercise for the spine with support from the obliques and glutes. Lie supine with the arms out wide and the knees bent. Drop both knees to one side and turn the head the other way, then change sides. Keep both shoulders heavy on the floor.','beginner','stretching'),
('recovery-cobra-stretch','Cobra Stretch','back','body weight','spine',ARRAY['abs','pectorals']::text[],ARRAY['Lie prone with the hands under the shoulders.','Set the breath before the first repetition.','Press up into a comfortable extension keeping the hips down, then lower slowly.','Lengthen the spine forward instead of crunching backwards.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Cobra Stretch is a stretching exercise for the spine with support from the abs and chest. Lie prone with the hands under the shoulders. Press up into a comfortable extension keeping the hips down, then lower slowly. Lengthen the spine forward instead of crunching backwards.','beginner','stretching'),
('recovery-sphinx-pose','Sphinx Pose','back','body weight','spine',ARRAY['pectorals']::text[],ARRAY['Lie prone propped on the forearms with elbows under the shoulders.','Set the breath before the first repetition.','Settle into a gentle extension and breathe for the prescribed time.','Relax the glutes and let the low back soften.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Sphinx Pose is a stretching exercise for the spine with support from the chest. Lie prone propped on the forearms with elbows under the shoulders. Settle into a gentle extension and breathe for the prescribed time. Relax the glutes and let the low back soften.','beginner','stretching'),
('recovery-downward-dog','Downward Dog','back','body weight','hamstrings',ARRAY['calves','shoulders']::text[],ARRAY['Start on all fours with the hands slightly ahead of the shoulders.','Set the breath before the first repetition.','Lift the hips up and back into an inverted V, pedalling the heels.','Bend the knees freely to keep the spine long.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Downward Dog is a stretching exercise for the hamstrings with support from the calves and shoulders. Start on all fours with the hands slightly ahead of the shoulders. Lift the hips up and back into an inverted V, pedalling the heels. Bend the knees freely to keep the spine long.','beginner','stretching'),
('recovery-lateral-lunge-groin-stretch','Lateral Lunge Stretch (Groin)','upper legs','body weight','adductors',ARRAY['glutes','hamstrings']::text[],ARRAY['Stand with the feet very wide and the toes forward.','Set the breath before the first repetition.','Shift the weight into one bent leg keeping the other straight, then change sides.','Keep both heels flat and the chest tall.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Lateral Lunge Stretch (Groin) is a stretching exercise for the adductors with support from the glutes and hamstrings. Stand with the feet very wide and the toes forward. Shift the weight into one bent leg keeping the other straight, then change sides. Keep both heels flat and the chest tall.','beginner','stretching'),
('recovery-kneeling-hip-flexor-reach','Kneeling Hip Flexor with Reach','upper legs','body weight','hip flexors',ARRAY['abs','glutes']::text[],ARRAY['Half kneel with the back knee under the hip.','Set the breath before the first repetition.','Tuck the pelvis, squeeze the back glute and reach the same-side arm overhead and across.','The reach only counts once the pelvis is tucked.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Kneeling Hip Flexor with Reach is a mobility exercise for the hip flexors with support from the abs and glutes. Half kneel with the back knee under the hip. Tuck the pelvis, squeeze the back glute and reach the same-side arm overhead and across. The reach only counts once the pelvis is tucked.','beginner','mobility'),
('recovery-wall-angels','Wall Angels','shoulders','body weight','upper back',ARRAY['delts']::text[],ARRAY['Stand with the back against a wall, feet slightly forward.','Set the breath before the first repetition.','Slide the arms up and down the wall keeping the wrists, elbows and low back in contact.','Go only as high as contact allows.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Wall Angels is a mobility exercise for the upper back with support from the delts. Stand with the back against a wall, feet slightly forward. Slide the arms up and down the wall keeping the wrists, elbows and low back in contact. Go only as high as contact allows.','beginner','mobility'),
('recovery-foam-roll-it-band','Foam Roll IT Band','upper legs','roller','quads',ARRAY['glutes']::text[],ARRAY['Lie on one side with a foam roller under the outer thigh.','Set the breath before the first repetition.','Roll slowly between the hip and the knee, pausing on tender spots and breathing.','Never roll directly over the knee joint.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Foam Roll IT Band is a mobility exercise for the quads with support from the glutes. Lie on one side with a foam roller under the outer thigh. Roll slowly between the hip and the knee, pausing on tender spots and breathing. Never roll directly over the knee joint.','beginner','mobility'),
('recovery-foam-roll-quads','Foam Roll Quads','upper legs','roller','quads',ARRAY['hip flexors']::text[],ARRAY['Lie prone with a foam roller under the front of the thighs.','Set the breath before the first repetition.','Roll slowly from the hip to just above the knee, pausing where it is tight.','Keep the abdominals engaged so the low back stays neutral.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Foam Roll Quads is a mobility exercise for the quads with support from the hip flexors. Lie prone with a foam roller under the front of the thighs. Roll slowly from the hip to just above the knee, pausing where it is tight. Keep the abdominals engaged so the low back stays neutral.','beginner','mobility'),
('recovery-foam-roll-upper-back','Foam Roll Upper Back','back','roller','upper back',ARRAY['spine']::text[],ARRAY['Lie supine with a foam roller across the upper back and the hands supporting the head.','Set the breath before the first repetition.','Roll slowly between the shoulder blades and the mid back, pausing to breathe.','Never roll the low back or the neck.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Foam Roll Upper Back is a mobility exercise for the upper back with support from the spine. Lie supine with a foam roller across the upper back and the hands supporting the head. Roll slowly between the shoulder blades and the mid back, pausing to breathe. Never roll the low back or the neck.','beginner','mobility'),
('recovery-foam-roll-glutes','Foam Roll Glutes','upper legs','roller','glutes',ARRAY['hip flexors']::text[],ARRAY['Sit on a foam roller with one ankle crossed over the opposite knee.','Set the breath before the first repetition.','Roll slowly over the glute of the crossed side, pausing on tender points.','Lean into the side being rolled for more pressure.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Foam Roll Glutes is a mobility exercise for the glutes with support from the hip flexors. Sit on a foam roller with one ankle crossed over the opposite knee. Roll slowly over the glute of the crossed side, pausing on tender points. Lean into the side being rolled for more pressure.','beginner','mobility'),
('recovery-single-leg-balance','Single-Leg Balance','upper legs','body weight','glutes',ARRAY['calves','abs']::text[],ARRAY['Stand tall near a support with the weight on one leg.','Set the breath before the first repetition.','Hold the balance for the prescribed time, keeping the standing foot quiet.','Fix the eyes on one point and grip the floor with the toes.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Single-Leg Balance is a balance exercise for the glutes with support from the calves and abs. Stand tall near a support with the weight on one leg. Hold the balance for the prescribed time, keeping the standing foot quiet. Fix the eyes on one point and grip the floor with the toes.','beginner','balance'),
('recovery-single-leg-rdl-reach','Single-Leg RDL Balance Reach','upper legs','body weight','hamstrings',ARRAY['glutes','spine']::text[],ARRAY['Stand on one leg with a soft knee.','Set the breath before the first repetition.','Hinge at the hip reaching the hands towards the floor and the free leg behind, then return tall.','Keep the hips square and the spine long the whole way.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Single-Leg RDL Balance Reach is a balance exercise for the hamstrings with support from the glutes and spine. Stand on one leg with a soft knee. Hinge at the hip reaching the hands towards the floor and the free leg behind, then return tall. Keep the hips square and the spine long the whole way.','intermediate','balance'),
('recovery-standing-9090-switch','Standing 90/90 Hip Switch','upper legs','body weight','hip flexors',ARRAY['glutes','abs']::text[],ARRAY['Stand tall holding a light support.','Set the breath before the first repetition.','Lift one knee to hip height, rotate it out and then in, and change sides in a rhythm.','Stay tall; do not lean away from the working hip.','Keep the tempo controlled: never rush the return phase.','Hold or repeat as prescribed, then move on.']::text[],'Standing 90/90 Hip Switch is a mobility exercise for the hip flexors with support from the glutes and abs. Stand tall holding a light support. Lift one knee to hip height, rotate it out and then in, and change sides in a rhythm. Stay tall; do not lean away from the working hip.','intermediate','mobility')
